/** Which lifecycle stage a game state belongs to (shown in every answer as `lifecycle.stage`). */
export const stageOfState = { no_game: "create", draft: "configure", awaiting_payment: "payment", scheduled: "ready", running: "live", ended: "post_game", cancelled: "close", did_not_start: "close" };

/** Actions about the organizer's account, not about one game: offered in every state to the organizer. */
export const alwaysActions = { organizer: ["list_games", "team_overview", "retire_team_member", "clone_game", "list_activity"], host: ["list_games"] };

// by: who makes the change. "organizer" / "host" = through this API; "human" = a person in the console or on the payment page; "system" = the game by itself.
// via: an action id (checked against the hypermedia table), or "human: ..." / "system: ...".
