  D13: { kind: "done", title: "The organizer's AI may retire a Host or Co-host, after the person's typed confirmation", question: "Keep it, or make retiring a console-only step?" },
  D14: { kind: "done", title: "The organizer's AI may make a new draft like an earlier game (never with the guest list)", question: "Keep it?" },
