  D24: { kind: "game_change", title: "A master key that expires or has limited rights", question: "Today a master key is all or nothing. Add expiring or scoped keys?" },
  D25: { kind: "game_change", title: "Review of a claim or a dispute by a Host or the organizer", question: "Winners come from the guests' phones and there is no review route. Add one, or accept?" },
