// status: READY | AUTOMATIC | HUMAN | NOT_APPLICABLE | GAP.   roles: who does it (organizer, host, human, system, guest).
// action: the gateway action (READY). via: a non-action way the AI already helps (FAQ, docs, envelope).  game_route: a route of the game that exists but the gateway does not call.
// solve (GAP): gateway_only | game_change.  verify: claims about the game's own source that the generator checks.
const R = (id, lifecycle, stage, roles, step, action, why = "", decision) => ({ id, lifecycle, stage, roles, step, status: "READY", action, why, ...(decision ? { decision } : {}) });
const A = (id, lifecycle, stage, roles, step, why) => ({ id, lifecycle, stage, roles, step, status: "AUTOMATIC", why });
const Hm = (id, lifecycle, stage, roles, step, why, game_route, decision) => ({ id, lifecycle, stage, roles, step, status: "HUMAN", why, ...(game_route ? { game_route } : {}), ...(decision ? { decision } : {}) });
const NA = (id, lifecycle, stage, roles, step, why) => ({ id, lifecycle, stage, roles, step, status: "NOT_APPLICABLE", why });
const G = (id, lifecycle, stage, roles, step, solve, decision, why, extra = {}) => ({ id, lifecycle, stage, roles, step, status: "GAP", solve, decision, why, ...extra });

