// ----------------------------------------------------------------------------------------------- the FAQ at each stage
// lifecycle + stage + role say where the question belongs. `a` may use the generator's {{placeholders}}.
const Q = (lifecycle, stage, role, q, a) => ({ lifecycle, stage, role, q, a });
export const lifecycleFaq = [
  Q("game", "create", "organizer", "How many games can I have in draft?", "At most {{max_drafts}} unpublished drafts at a time. An unpublished draft is forgotten after {{draft_days}} days. Cancel an old draft to make room."),
  Q("game", "create", "organizer", "How far ahead can I start?", "At most {{max_ahead_days}} days ahead while the game is not paid. The time must include the time zone."),
  Q("game", "configure", "organizer", "Can I change the game after I made it?", "Yes, with change_settings, until the game starts. The prize list replaces the old one, so send every prize. After the start the settings are locked."),
  Q("game", "configure", "organizer", "Can I set who can join, breaks, the company name and colour, or the Co-host limit?", "Yes, with change_extra_settings, before the game starts: who can join (anyone with the link, or only a list the organizer loads), breaks during the game, an opening and a closing moment, the company name and colour on the tickets, and how many people a Co-host may list ({{cohost_limit_min}} to {{cohost_limit_max}}). Only plain messages and lucky draws can be set: no links, videos or logos. A break or moment that the organizer set in the console with a link cannot be changed here."),
  Q("game", "configure", "organizer", "What is host-calling mode?", "Instead of the software calling every number, a Host presses a button in their own browser for every number. The AI cannot press it, so the game waits for a person. It needs the organizer's typed confirmation, and is not recommended."),
  Q("game", "configure", "organizer", "Can I set the language of the game?", "Not through the API: the game has no language setting (decision D20)."),
  Q("game", "invite", "organizer", "How do guests get in?", "They open the guest link (links.guest in game_status) on their phones. Today guests join with their mobile number; joining by ID only is not supported yet (decision D8). Guest names and numbers are never shown to the AI."),
  Q("game", "invite", "organizer", "Can I load a guest list through the AI?", "No. A guest list is personal data, so the organizer loads it in their own console. The AI can switch guest invitations on and set how many each guest may invite."),
  Q("game", "payment", "organizer", "Who pays, and can the AI pay?", "The AI can never pay. The AI makes ONE payment link; a person opens it and pays on the payment page through Razorpay. The link works for {{paylink_ttl_days}} days and a new link cancels the old one."),
  Q("game", "payment", "organizer", "How do I get a receipt or invoice?", "Not through the API (decision D19). The game sends them to the organizer by e-mail."),
  Q("game", "ready", "organizer", "Can I still cancel after paying?", "Yes, before the start (cancel_game_preview, then cancel_game). A paid game becomes credit for the next game; there are no refunds."),
  Q("game", "start", "organizer", "How do I start the game?", "By default you press nothing: a paid game starts by itself at its start time. If the organizer chose Start by hand in the console, the organizer or a Host presses Start at that time: ask live_handover with step start and give the person the page it returns."),
  Q("game", "start", "host", "What can I do before the start?", "See how many guests have joined, check the start time, and send one short message to every phone. You cannot add or remove guests: that needs personal data and is done by the organizer in the console."),
  Q("game", "live", "host", "Who calls the numbers?", "The software, from a public random source, at the chosen speed. Nobody, not the organizer, a Host or the AI, can choose or change them."),
  Q("game", "live", "organizer", "Can the AI pause or stop the game?", "No. Pause, resume and stop are live actions, so the AI never presses or files them (the AI hand-over rule). It calls live_handover, gives the organizer the console page and says in one sentence what to press. Only their browser can sign it. Stopping cannot be undone."),
  Q("game", "live", "host", "A guest says they won. What do I do?", "Winners are decided by the guests' phones agreeing; nobody approves or rejects a claim. The game has no dispute route (decision D25). Tell the organizer. If play must stop, the AI calls live_handover (step pause) and gives the organizer the console page to press it themselves."),
  Q("game", "finish", "organizer", "Who decides the winners and how do I hand over prizes?", "The guests' phones decide, by agreement. Read the results and the prizes (ticket numbers only), hand the prize over, then tick it with mark_prize_given. The organizer sees the winners' names in the console."),
  Q("game", "post_game", "organizer", "Where is the report?", "report_link_status says whether it is ready and sent. The link goes to the organizer's e-mail and is never shown by the API."),
  Q("game", "post_game", "organizer", "Can I get certificates or an export?", "Not through the API (decisions D21 and D22): the game has neither."),
  Q("game", "close", "organizer", "When is guest data erased?", "By the system, within 24 hours of the end of the game. You can erase it earlier with erase_guest_data after typing the sentence shown. Winner records stay."),
  Q("game", "rerun", "organizer", "Can I bring a cancelled game back?", "Yes, if it was paid: reopen_game moves it to a new date within 365 days of the payment, after the organizer types the sentence shown. The payment stays with the game, nothing more is due, and the AI pays nothing. Guests must join again. A game that was never paid cannot be reopened: use clone_game."),
  Q("game", "rerun", "organizer", "How do I run the same game again?", "Use clone_game. It makes a new draft with the same settings and prizes under a new game id. The date, the payment, the guests and the Hosts are not copied. Without a start time the draft waits until you set one."),
  Q("game", "status_audit", "organizer", "Can I see what the AI did?", "Every answer says the state. Use list_activity to read the gateway's own log of calls: time, action, game id, which kind of key, and the result. It never holds keys, inputs or personal data, and it is kept in the gateway's memory only, so it is lost when the gateway restarts (decision D28). The game's own audit trail does not label calls made with the organizer key (decision D6)."),
  Q("organizer", "key_and_signin", "organizer", "Where do I get the organizer key and what happens if it leaks?", "Sign in to your console and copy it (it starts with ctk_). Anyone who holds it can use it. If it leaks, retire it in the console at once: a retired key stops working immediately. A safer choice is the game's own AI work key (it starts with cta_): it cannot pay, make a payment link, cancel, erase, copy, reopen or handle keys and the team. The organizer pastes it in; or the organizer key can ask the game to e-mail a fresh 24-hour one (request_fresh_ai_key)."),
  Q("organizer", "key_and_signin", "organizer", "Does the key expire?", "The gateway never stores it. An organizer key does not expire by itself (decision D24); retire it in the console. A fresh AI work key from request_fresh_ai_key works for 24 hours."),
  Q("organizer", "team", "organizer", "How do I add a Host?", "In the console (up to {{max_hosts}} Hosts). It needs the Host's name and e-mail or mobile number, so the AI cannot do it. The Host gets a one-time link and then a key."),
  Q("organizer", "team", "organizer", "How do I remove a Host?", "Ask the AI to retire the Host (retire_team_member, using the id from team_overview) and type the sentence shown. The key stops at once."),
  Q("organizer", "games", "organizer", "Can I edit, cancel or copy a game?", "Yes: change_settings, cancel_game (before the start) and clone_game."),
  Q("organizer", "payments", "organizer", "Is there a payment history?", "Per game you can see whether it is paid (payment_status). A history of payments and receipts across games is not available through the API (decision D19)."),
  Q("organizer", "key_care", "organizer", "How do I see my keys?", "list_signin_keys shows each key's id, kind, whether it is retired, and when it was made. It never shows a key itself."),
  Q("organizer", "key_care", "organizer", "How do I retire or rotate a key?", "In the console. A key must not retire or replace itself, so the AI does not do it."),
  Q("organizer", "data", "organizer", "Can I export or erase my data?", "Erase the guest data of a game with erase_guest_data. An export is not available through the API (decision D22). Closing the whole account is done in the console only."),
  Q("organizer", "support", "organizer", "Who do I ask when this does not answer?", "Say 'I do not know that' and point to the game's Trust page and the organizer's console. There is no support ticket route (decision D29)."),
  Q("host", "receive", "host", "How do I get a host key?", "The organizer adds you in the console. You get a one-time link by e-mail or WhatsApp and confirm your e-mail or mobile. The key (cth_) is then used here. The AI cannot create a Host."),
  Q("host", "assigned", "host", "Which games can I see?", "Use list_games to see the published games of the organizer's account (id, time and head-count only, no drafts), or give the game id the organizer named to game_status."),
  Q("host", "prechecks", "host", "What should I check before the start?", "The start time, that the game is scheduled (paid), how many guests joined, and when the data is erased. Send one short message if the organizer wants."),
  Q("host", "run", "host", "Can I pause or stop the game?", "Not through the AI: these are live actions. The AI calls live_handover and gives you the page to press it yourself: your own Host page, or the organizer's console."),
  Q("host", "run", "host", "Can I press the next number?", "Not through this API (decision D27): in host-calling mode it needs your own browser."),
  Q("host", "edge_cases", "host", "Something is wrong. What now?", "Tell the organizer. If play must stop, call live_handover (step pause) so the organizer gets the console page to press it themselves. You cannot remove guests or settle a dispute."),
  Q("host", "handover", "host", "Can I hand over or leave?", "Not through the API (decision D26). Tell the organizer; they retire your key."),
  Q("host", "end", "host", "How do I hand over prizes?", "List the prizes (ticket numbers only), hand the prize to the winner, then tick it with mark_prize_given. The organizer sees winners' names in the console."),
  Q("host", "post_game", "host", "What happens to the data?", "Guest data is erased by the system within 24 hours of the end. The report goes to the organizer's e-mail."),
  Q("host", "retire", "host", "How does my key end?", "The organizer retires it. You cannot retire it yourself (decision D26)."),
];
